const fs = require('fs');

const [A, B] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const ana = A % 3;
let beatriz = B % 3;

if (beatriz === ana) {
  beatriz = (beatriz + 1) % 3;
